// Bit-exact parity test: C++ engine output vs vectors generated by the real
// Python ops (tools/gen_vectors.py). Compares raw bytes, not tolerance.
// Iterates every case in vectors/cases.json. Generate vectors first with:
//   .venv/bin/python cpp/engine/tools/gen_vectors.py --out cpp/engine/tests/vectors
#include "engine.hpp"

#include <mlx/mlx.h>

#include <cassert>
#include <cstdint>
#include <cstdio>
#include <exception>
#include <fstream>
#include <string>
#include <vector>

namespace mx = mlx::core;
using namespace veystrix::engine;

static bool bit_equal(const mx::array& a, const mx::array& b) {
  if (a.shape() != b.shape()) return false;
  mx::array av = mx::astype(mx::reshape(a, {-1}), mx::uint32);
  mx::array bv = mx::astype(mx::reshape(b, {-1}), mx::uint32);
  mx::eval(av, bv);
  if (av.size() != bv.size()) return false;
  const uint32_t* pa = av.data<uint32_t>();
  const uint32_t* pb = bv.data<uint32_t>();
  for (size_t i = 0; i < av.size(); ++i)
    if (pa[i] != pb[i]) return false;
  return true;
}

static int run_case(const std::string& root, const std::string& name, int G) {
  std::string dir = root + "/" + name;
  auto load = [&](const char* n) { return mx::load(dir + "/" + n + ".npy"); };

  mx::array logits = load("router_logits");
  mx::array exp_inds = load("router_indices");
  int K = static_cast<int>(exp_inds.shape().back());
  RouterOutput r = router(logits, K, 0.0f);
  mx::eval(r.indices, r.scores);
  if (!bit_equal(r.indices, exp_inds)) {
    std::fprintf(stderr, "[%s] ROUTER INDICES differ\n", name.c_str());
    return 1;
  }

  mx::array x = load("x"), route = load("route"), scores = load("scores");
  mx::array gw = load("gw"), gs = load("gs"), gb = load("gb");
  mx::array uw = load("uw"), us = load("us"), ub = load("ub");
  mx::array dw = load("dw"), ds = load("ds"), db = load("db");
  mx::array expected = load("expected");
  ExpertWeights w(Q4Projection(gw, gs, gb), Q4Projection(uw, us, ub),
                  Q4Projection(dw, ds, db), G, 4);
  mx::array out = moe_block(x, route, scores, w);
  mx::eval(out);

  // RMSNorm and greedy sampler parity.
  bool extra_ok = true;
  try {
    mx::array nx = load("norm_x"), nw = load("norm_w"), ne = load("norm_expected");
    mx::array norm_out = rms_norm(nx, nw, 1e-6f);
    mx::eval(norm_out);
    extra_ok = extra_ok && bit_equal(norm_out, ne);
    mx::array sl = load("sample_logits"), ge = load("greedy");
    mx::array greedy = sample_greedy(sl);
    mx::eval(greedy);
    extra_ok = extra_ok && bit_equal(greedy, ge);
  } catch (const std::exception& e) {
    std::fprintf(stderr, "[%s] extra primitive load failed: %s\n", name.c_str(), e.what());
    extra_ok = false;
  }
  if (!extra_ok) {
    std::fprintf(stderr, "[%s] RMSNorm or greedy sampler differs\n", name.c_str());
    return 1;
  }
  if (!bit_equal(out, expected)) {
    mx::array ov = mx::astype(mx::reshape(out, {-1}), mx::uint32);
    mx::array ev = mx::astype(mx::reshape(expected, {-1}), mx::uint32);
    mx::eval(ov, ev);
    size_t n = ov.size() < ev.size() ? ov.size() : ev.size();
    const uint32_t* a = ov.data<uint32_t>();
    const uint32_t* b = ev.data<uint32_t>();
    size_t diff = n;
    for (size_t i = 0; i < n; ++i) if (a[i] != b[i]) { diff = i; break; }
    std::fprintf(stderr,
                 "[%s] MOE BLOCK differs: out=%zu exp=%zu first diff %zu "
                 "(0x%08x vs 0x%08x)\n", name.c_str(), out.size(), expected.size(),
                 diff, diff < n ? a[diff] : 0, diff < n ? b[diff] : 0);
    return 1;
  }
  std::printf("  [%s] OK (router + moe_block bit-identical)\n", name.c_str());
  return 0;
}

int main(int argc, char** argv) {
  std::string root = argc > 1 ? argv[1] : "tests/vectors";

  // Single real-checkpoint case: pass "--real <dir>" (meta.json present, no cases.json).
  if (argc > 2 && std::string(argv[2]) == "--real") {
    std::string dir = argv[1];
    auto load = [&](const char* n) { return mx::load(dir + "/" + n + ".npy"); };
    mx::array gw = load("gw"), gs = load("gs"), gb = load("gb");
    mx::array uw = load("uw"), us = load("us"), ub = load("ub");
    mx::array dw = load("dw"), ds = load("ds"), db = load("db");
    mx::array x = load("x"), route = load("route"), scores = load("scores");
    mx::array expected = load("expected");
    ExpertWeights w(Q4Projection(gw, gs, gb), Q4Projection(uw, us, ub),
                    Q4Projection(dw, ds, db), 32, 4);
    mx::array out = moe_block(x, route, scores, w);
    mx::eval(out);
    if (!bit_equal(out, expected)) {
      std::fprintf(stderr, "[real] MOE BLOCK differs on real Qwen weights\n");
      return 1;
    }
    std::printf("[real] OK (bit-identical on real Qwen expert weights)\n");
    return 0;
  }

  // Read cases.json for names + group sizes (minimal hand-rolled parse).
  std::ifstream f(root + "/cases.json");
  if (!f) { std::fprintf(stderr, "cases.json missing; run gen_vectors.py\n"); return 2; }
  std::vector<std::pair<std::string,int>> cases;
  std::string line, cur;
  int group = 32;
  bool in_case = false;
  while (std::getline(f, line)) {
    if (line.find("\"dir\"") != std::string::npos) {
      auto q1 = line.find('"', line.find(':') + 1);
      auto q2 = line.find('"', q1 + 1);
      cur = line.substr(q1 + 1, q2 - q1 - 1);
      in_case = true;
    } else if (in_case && line.find("\"G\"") != std::string::npos) {
      auto colon = line.find(':');
      group = std::stoi(line.substr(colon + 1));
    }
    if (in_case && line.find("}") != std::string::npos) {
      if (!cur.empty()) cases.push_back({cur, group});
      cur.clear(); in_case = false; group = 32;
    }
  }
  if (cases.empty()) { std::fprintf(stderr, "no cases parsed\n"); return 2; }
  int failed = 0;
  for (auto& c : cases) failed += run_case(root, c.first, c.second);
  if (failed) { std::fprintf(stderr, "%d case(s) FAILED\n", failed); return 1; }
  std::printf("test_engine_parity OK (%zu cases bit-identical to Python)\n", cases.size());
  return 0;
}
